mapper.select:
-- Count submitted input values for one option.
SELECT
    count(1)
FROM application_input_values aiv
WHERE aiv.requirement_id = #{requirementId}
  AND aiv.option_code = #{optionCode}

mapper.delete:
-- Delete options while replacing a requirement before progress values exist.
DELETE FROM announcement_input_options
WHERE requirement_id = #{requirementId}

-- Delete one option when no submitted input value references it.
DELETE FROM announcement_input_options
WHERE requirement_id = #{requirementId}
  AND option_code = #{optionCode}

-- Delete dynamic input requirement before progress values exist.
DELETE FROM announcement_input_requirements
WHERE id = #{requirementId}

mapper.update:
-- Update dynamic input option label and display order.
UPDATE announcement_input_options
SET
    option_label = #{optionLabel},
    sort_order = #{sortOrder},
    updated_by = #{actorUserId},
    updated_at = now()
WHERE id = #{optionId}
  AND requirement_id = #{requirementId}
  AND option_code = #{optionCode}

mapper.delete:
-- Replace submitted dynamic input values for one progress.
DELETE FROM application_input_values
WHERE progress_id = #{progressId}
